messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>

<!-- Import Map for Three.js r160 -->
<script type="importmap">
    {
        "imports": {
            "three": "./three.module.js"
        }
    }
</script>

<script type="module">
import * as THREE from './three.module.js';

// --- Configuration ---
const CYCLE_DURATION = 10; // seconds
const STAND_TIME = 2;
const WALK_TIME = 3;
const RUN_TIME = 3;
const GROUND_SPEED = 0.5;

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202025);
scene.fog = new THREE.Color(0x202025);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(5, 3, 6);
camera.lookAt(0, 1.5, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lights ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 1024;
dirLight.shadow.mapSize.height = 1024;
scene.add(dirLight);

// --- Materials ---
const matBody = new THREE.MeshStandardMaterial({ color: 0x3366ff, roughness: 0.7 });
const matHead = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.7 });
const matLeg = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.7 });
const matFoot = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.7 });
const matTreadmill = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });

// --- Helper: Create Limb ---
function createLimb(width, height, depth, material) {
    const geo = new THREE.BoxGeometry(width, height, depth);
    const mesh = new THREE.Mesh(geo, material);
    // Pivot adjustment: default box origin is center. 
    // We will handle pivots manually in the hierarchy or by setting position relative to parent.
    // To simplify, we will keep the geometry centered and adjust the child position in the hierarchy.
    return mesh;
}

// --- Build Humanoid ---
const humanGroup = new THREE.Group();
scene.add(humanGroup);

// 1. Torso
const torsoHeight = 1.2;
const torsoGeo = new THREE.BoxGeometry(0.6, torsoHeight, 0.4);
const torso = new THREE.Mesh(torsoGeo, matBody);
torso.position.y = 1.5; // Center of mass
torso.castShadow = true;
humanGroup.add(torso);

// 2. Head
const headGeo = new THREE.BoxGeometry(0.4, 0.45, 0.4);
const head = new THREE.Mesh(headGeo, matHead);
head.position.y = 0.6; // relative to torso center
head.castShadow = true;
torso.add(head);

// 3. Legs (Pivots at Hip)
const legGeo = new THREE.BoxGeometry(0.25, 1.2, 0.25);
const leftLegPivot = new THREE.Group();
leftLegPivot.position.set(-0.2, -0.6, 0); // Offset from torso center
torso.add(leftLegPivot);

const leftLegMesh = new THREE.Mesh(legGeo, matLeg);
leftLegMesh.position.y = -0.6; // Center the box at the pivot
leftLegPivot.add(leftLegMesh);

// Left Foot
const footGeo = new THREE.BoxGeometry(0.25, 0.15, 0.4);
const leftFoot = new THREE.Mesh(footGeo, matFoot);
leftFoot.position.set(0, -1.15, 0.1); // relative to leg mesh center
leftLegPivot.add(leftFoot);

// Right Leg
const rightLegPivot = new THREE.Group();
rightLegPivot.position.set(0.2, -0.6, 0);
torso.add(rightLegPivot);

const rightLegMesh = new THREE.Mesh(legGeo, matLeg);
rightLegMesh.position.y = -0.6;
rightLegPivot.add(rightLegMesh);

// Right Foot
const rightFoot = new THREE.Mesh(footGeo, matFoot);
rightFoot.position.set(0, -1.15, 0.1);
rightLegPivot.add(rightFoot);

// 4. Arms (Pivots at Shoulder)
const armGeo = new THREE.BoxGeometry(0.2, 1.0, 0.2);

// Left Arm
const leftArmPivot = new THREE.Group();
leftArmPivot.position.set(-0.4, 0.5, 0); // Shoulder
torso.add(leftArmPivot);

const leftArmMesh = new THREE.Mesh(armGeo, matLeg);
leftArmMesh.position.y = -0.5;
leftArmPivot.add(leftArmMesh);

// Right Arm
const rightArmPivot = new THREE.Group();
rightArmPivot.position.set(0.4, 0.5, 0);
torso.add(rightArmPivot);

const rightArmMesh = new THREE.Mesh(armGeo, matLeg);
rightArmMesh.position.y = -0.5;
rightArmPivot.add(rightArmMesh);

// --- Environment ---
// Treadmill Base
const treadGeo = new THREE.BoxGeometry(3, 0.2, 6);
const treadmill = new THREE.Mesh(treadGeo, matTreadmill);
treadmill.position.set(0, -0.1, 0);
treadmill.receiveShadow = true;
scene.add(treadmill);

// Moving strip visual (simple plane)
const stripGeo = new THREE.PlaneGeometry(2.8, 5);
const stripMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const strip = new THREE.Mesh(stripGeo, stripMat);
strip.rotation.x = -Math.PI / 2;
strip.position.set(0, 0.01, 0);
scene.add(strip);

// --- Animation State ---
// We track the global cycle time.
let globalTime = 0;

// --- Animation Loop ---
const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();
    globalTime += delta;

    // Normalize time to cycle duration
    const t = globalTime % CYCLE_DURATION;

    // 1. Determine State
    let state = 'stand';
    if (t >= STAND_TIME && t < STAND_TIME + WALK_TIME) state = 'walk';
    else if (t >= STAND_TIME + WALK_TIME && t < STAND_TIME + WALK_TIME + RUN_TIME) state = 'run';

    // 2. Calculate Parameters based on State
    let walkSpeed = 0;
    let walkAmp = 0;
    let walkKnee = 0;
    let walkLean = 0;

    let runSpeed = 0;
    let runAmp = 0;
    let runKnee = 0;
    let runLean = 0;

    if (state === 'stand') {
        walkSpeed = 0; walkAmp = 0; walkKnee = 0; walkLean = 0;
        runSpeed = 0; runAmp = 0; runKnee = 0; runLean = 0;
    } else if (state === 'walk') {
        walkSpeed = 4.0; 
        walkAmp = 0.6; 
        walkKnee = 0.3;
        walkLean = 0.05;

        // Dampen run params
        runSpeed = 0; runAmp = 0; runKnee = 0; runLean = 0;
    } else if (state === 'run') {
        walkSpeed = 0; walkAmp = 0; walkKnee = 0; walkLean = 0;

        runSpeed = 8.0;
        runAmp = 1.0; // High knees
        runKnee = 0.5;
        runLean = 0.15; // Forward lean
    }

    // 3. Apply Animation

    // --- Treadmill Ground Movement (Visual only) ---
    // We animate the texture offset or position. Let's just move the strip.
    const speedVal = (state === 'stand') ? 0 : (state === 'walk' ? 0.5 : 1.5);
    strip.position.z = (globalTime * speedVal * 2) % 5;

    // --- Limb Logic ---
    // Helper to calculate sine wave for swinging
    const swing = (time, speed, phaseOffset = 0) => Math.sin(time * speed + phaseOffset);
    const swingAbs = (time, speed, phaseOffset = 0) => Math.abs(Math.sin(time * speed + phaseOffset));

    // Left Leg
    const lSwing = swing(globalTime, walkSpeed, 0);
    leftLegPivot.rotation.x = -lSwing * walkAmp;
    // Knee bend (simple rotation of the leg mesh relative to hip, or just rotation on Z)
    // For a box, bending "knee" is usually rotating the whole leg mesh on Z axis slightly
    leftLegMesh.rotation.z = lSwing * walkKnee;
    // Foot angle
    leftFoot.rotation.x = -0.2; // Slight toe up

    // Right Leg
    const rSwing = swing(globalTime, walkSpeed, Math.PI);
    rightLegPivot.rotation.x = -rSwing * walkAmp;
    rightLegMesh.rotation.z = rSwing * walkKnee;
    rightFoot.rotation.x = -0.2;

    // Left Arm
    // Arms swing opposite to legs
    const lArmSwing = swing(globalTime, walkSpeed, Math.PI);
    leftArmPivot.rotation.x = lArmSwing * walkAmp;

    // Right Arm
    const rArmSwing = swing(globalTime, walkSpeed, 0);
    rightArmPivot.rotation.x = rArmSwing * walkAmp;

    // --- Running Specifics ---
    if (state === 'run') {
        // Higher knees
        leftLegPivot.rotation.x = -swing(globalTime, runSpeed, 0) * runAmp;
        rightLegPivot.rotation.x = -swing(globalTime, runSpeed, Math.PI) * runAmp;

        // More "bent" look
        leftLegMesh.rotation.z = swing(globalTime, runSpeed, 0) * runKnee;
        rightLegMesh.rotation.z = swing(globalTime, runSpeed, Math.PI) * runKnee;

        // Arms swing higher and faster
        leftArmPivot.rotation.x = swing(globalTime, runSpeed, Math.PI) * runAmp;
        rightArmPivot.rotation.x = swing(globalTime, runSpeed, 0) * runAmp;
    }

    // --- Global Body Transforms ---
    // Lean
    humanGroup.rotation.x = (state === 'run' ? runLean : walkLean);

    // Bobbing
    const bobSpeed = (state === 'stand') ? 0 : (state === 'walk' ? walkSpeed : runSpeed);
    const bobHeight = (state === 'stand') ? 0 : (state === 'walk' ? 0.05 : 0.15);
    const bob = Math.sin(globalTime * bobSpeed) * bobHeight;
    humanGroup.position.y = bob;

    // --- Camera Slight Zoom ---
    // Just a subtle effect to make it feel alive
    camera.position.y = 3 + Math.sin(globalTime * 0.5) * 0.1;

    renderer.render(scene, camera);
}

// Handle Resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start
animate();

</script>
</body>
</html>
```
